-- ==========================================================================
--  14. 通知公告数据
-- ==========================================================================
DELETE FROM `sys_notice`;

INSERT INTO `sys_notice` (`id`, `title`, `content`, `notice_type`, `scope`, `class_id`, `target_role`, `publisher_id`, `publisher_name`, `publisher_role`, `status`, `publish_time`) VALUES
  (1, '关于开展2026-2027学年第一学期期中教学检查的通知', '<p>各学院、各班级：</p><p>为加强教学过程管理，切实提高教学质量，教务处决定于第9-10周开展期中教学检查。请各班主任组织本班学生认真配合，如实填写教学评价表。</p><p>检查内容包括：教学进度执行情况、课堂教学秩序、作业布置与批改情况、实验实践教学开展情况。</p>', '教务', 'ALL', NULL, NULL, 2, '张国华', '教务处', 1, '2026-09-25 09:00:00'),
  (2, '关于2026-2027学年第一学期期末考试安排的通知', '<p>各位同学：</p><p>本学期期末考试将于第17-18周进行，具体考试时间及地点将于第15周公布。请同学们合理安排复习时间，诚信应考。</p><p>考试违纪将按《学生手册》相关规定严肃处理。</p>', '教务', 'ALL', NULL, NULL, 3, '李慧敏', '教务处', 1, '2026-09-26 09:00:00'),
  (3, '关于评选2025-2026学年优秀学生的通知', '<p>各位同学：</p><p>本年度优秀学生评选工作现已启动，评选条件：学年平均绩点3.0以上，无违纪记录，综合素质测评成绩排名专业前30%。</p><p>请符合条件的同学于10月20日前向班主任提交申请材料。</p>', '通知', 'ALL', NULL, NULL, 2, '张国华', '教务处', 1, '2026-09-27 09:00:00'),
  (4, '2026届毕业生就业指导讲座通知', '<p>为帮助毕业班同学了解就业形势、提升求职技能，学院特邀请知名企业HR开展就业指导讲座。</p><p>时间：10月15日 14:00<br/>地点：第一教学楼报告厅<br/>主讲人：某科技公司人力资源总监</p>', '通知', 'ALL', NULL, NULL, 3, '李慧敏', '教务处', 1, '2026-09-28 09:00:00'),
  (5, '关于调整作息时间的通知', '<p>各位同学：</p><p>自10月8日起执行冬季作息时间，上午第一节课上课时间调整为8:00，下午第一节课调整为14:00，晚自习19:00-21:00。</p>', '通知', 'ALL', NULL, NULL, 2, '张国华', '教务处', 1, '2026-09-29 09:00:00'),
  (6, '计算机学院23级学风建设主题班会安排', '<p>本班定于10月10日（周五）下午15:00在R001教室召开学风建设主题班会，请全体同学准时参加，不得无故缺席。</p>', '通知', 'CLASS', 1, NULL, 4, '夏军', '班主任', 1, '2026-09-30 09:00:00'),
  (7, '关于软件工程2301班课程实践项目分组通知', '<p>本学期《Spring Boot 企业级开发》课程实践项目要求4人一组，请各位于本周五前完成分组并将名单报给班长。</p>', '通知', 'CLASS', 4, NULL, 4, '夏军', '班主任', 1, '2026-10-01 09:00:00'),
  (8, '关于国家奖学金评审结果的公示', '<p>经学生申请、学院初评、学校评审委员会审定，现将2025-2026学年国家奖学金拟推荐名单予以公示，公示期5个工作日。</p>', '公告', 'ALL', NULL, NULL, 3, '李慧敏', '教务处', 1, '2026-10-02 09:00:00'),
  (9, '图书馆国庆节后开放时间调整公告', '<p>国庆节后图书馆恢复正常开放时间：周一至周五 8:00-22:00，周六周日 9:00-21:00。</p>', '公告', 'ALL', NULL, NULL, 2, '张国华', '教务处', 1, '2026-10-03 09:00:00'),
  (10, '关于加强学生宿舍安全管理的通知', '<p>近期将开展学生宿舍安全专项检查，重点检查违规电器使用、私拉电线等情况，请同学们自觉配合。</p>', '通知', 'ALL', NULL, NULL, 3, '李慧敏', '教务处', 1, '2026-10-04 09:00:00');
